/**
 * Python-flavoured exception objects.
 *
 * The original program lets exceptions escape `main()`, so the interpreter
 * prints a traceback and exits with status 1.  We model just enough of the
 * hierarchy to reproduce that behaviour.
 */

export class PyException extends Error {
  constructor(pyType, message) {
    super(message);
    this.pyType = pyType;
    this.pyMessage = message;
  }

  /** `str(exc)` — what CPython prints after the exception name. */
  toPyString() {
    return this.pyMessage;
  }
}

export class PyValueError extends PyException {
  constructor(message) {
    super('ValueError', message);
  }
}

export class PyTypeError extends PyException {
  constructor(message) {
    super('TypeError', message);
  }
}

/** Raised by our `int()` / `float()` ports; carries no traceback of its own. */
export class PyConversionError extends PyValueError {}

/**
 * Frames of the traceback CPython emits for an uncaught exception raised from
 * `encode_canonical_json`.  Mirrors the frozen-import paths that PyInstaller
 * reports for the bundled executable.
 */
export const CANONICAL_ENCODE_TRACEBACK = [
  '  File "test10.py", line 26, in <module>',
  '  File "test10.py", line 18, in main',
  '  File "canonicaljson/__init__.py", line 84, in encode_canonical_json',
  '  File "json/encoder.py", line 200, in encode',
  '  File "json/encoder.py", line 258, in iterencode',
];

/**
 * Write the CPython-style traceback for `exc` to stderr, followed by the
 * PyInstaller bootloader's failure notice.
 */
export function printTraceback(exc, frames = CANONICAL_ENCODE_TRACEBACK) {
  const lines = ['Traceback (most recent call last):', ...frames];
  const detail = exc instanceof PyException ? exc.toPyString() : String(exc && exc.message);
  lines.push(detail ? `${exc.pyType || 'Exception'}: ${detail}` : `${exc.pyType || 'Exception'}`);
  lines.push(
    `[PYI-${process.pid}:ERROR] Failed to execute script 'test10' due to unhandled exception!`,
  );
  process.stderr.write(lines.join('\n') + '\n');
}

