/**
 * `repr()` for `bytes` and `str`.
 *
 * The program prints `bytes` objects, and `print()` falls back to `repr()` for
 * them — so the visible output is CPython's `PyBytes_Repr()`, not the decoded
 * text.  `strRepr` is needed for argparse's `invalid int value: '...'` message.
 */

import { isPrintable } from './pyunicode.mjs';

const SQ = 0x27; // '
const DQ = 0x22; // "
const BACKSLASH = 0x5c;

function hex2(byte) {
  return byte.toString(16).padStart(2, '0');
}

/**
 * `PyBytes_Repr()` with smart quotes.
 *
 * Single quotes are used unless the payload contains a `'` and no `"`.  Bytes
 * outside printable ASCII — including DEL (0x7f) and everything above it — are
 * escaped as `\xhh` with lowercase hex digits.
 */
export function bytesRepr(bytes) {
  let hasSingle = false;
  let hasDouble = false;
  for (const byte of bytes) {
    if (byte === SQ) hasSingle = true;
    else if (byte === DQ) hasDouble = true;
  }
  const quote = hasSingle && !hasDouble ? DQ : SQ;
  const quoteChar = String.fromCharCode(quote);

  let out = `b${quoteChar}`;
  for (const byte of bytes) {
    if (byte === quote || byte === BACKSLASH) out += `\\${String.fromCharCode(byte)}`;
    else if (byte === 0x09) out += '\\t';
    else if (byte === 0x0a) out += '\\n';
    else if (byte === 0x0d) out += '\\r';
    else if (byte < 0x20 || byte >= 0x7f) out += `\\x${hex2(byte)}`;
