/**
 * The mapping between Python values and their JavaScript stand-ins.
 *
 * | Python  | here                     |
 * |---------|--------------------------|
 * | `str`   | `string`                 |
 * | `int`   | `bigint`                 |
 * | `float` | `number`                 |
 * | `bool`  | `boolean`                |
 * | `None`  | `null`                   |
 * | `list`  | `Array`                  |
 * | `dict`  | `Map` (insertion-ordered)|
 *
 * Keeping `int` and `float` on distinct JavaScript types is what lets the
 * encoder reproduce `1` vs `1.0` without carrying wrapper objects around.
 */

export const isPyStr = (value) => typeof value === 'string';
export const isPyInt = (value) => typeof value === 'bigint';
export const isPyFloat = (value) => typeof value === 'number';
export const isPyBool = (value) => typeof value === 'boolean';
export const isPyNone = (value) => value === null;
export const isPyList = (value) => Array.isArray(value);
export const isPyDict = (value) => value instanceof Map;

/** Build a `dict` from `[key, value]` pairs, preserving insertion order. */
export function pyDict(entries) {
  return new Map(entries);
}

