/**
 * A port of `json.JSONEncoder` — specifically of `_make_iterencode()`, the
 * pure-Python generator path.
 *
 * Reproducing the generator faithfully matters: `iterencode()` is observable
 * through the *number of chunks* it yields, and the chunk boundaries are an
 * artefact of how the original code interleaves separators.  Lists prepend the
 * pending separator onto the following item (one chunk per element), whereas
 * dicts yield the separator, the key and the key separator as three chunks.
 */

import { PyValueError, PyTypeError } from '../pyerrors.mjs';
import { floatRepr } from '../pyfloat.mjs';
import { intRepr } from '../pyint.mjs';
import { codePointCompare } from '../pyunicode.mjs';
import {
  isPyBool,
  isPyDict,
  isPyFloat,
  isPyInt,
  isPyList,
  isPyNone,
  isPyStr,
} from '../pytypes.mjs';
import { encodeBasestring } from './escape.mjs';

/** `sorted(dct.items())` restricted to the key types a dict can actually hold. */
function sortItems(entries) {
  const keys = entries.map(([key]) => key);
  if (keys.every(isPyStr)) {
    return entries.slice().sort((a, b) => codePointCompare(a[0], b[0]));
  }
  if (keys.every((key) => isPyInt(key) || isPyFloat(key) || isPyBool(key))) {
    const asNumber = (key) => (isPyBool(key) ? Number(key) : Number(key));
    return entries.slice().sort((a, b) => asNumber(a[0]) - asNumber(b[0]));
  }
  throw new PyTypeError("'<' not supported between instances of dict keys");
}

export class JSONEncoder {
  constructor(options = {}) {
    const {
      skipkeys = false,
      checkCircular = true,
      allowNan = true,
      sortKeys = false,
      indent = null,
      separators = null,
      defaultFn = null,
    } = options;

    this.skipkeys = skipkeys;
    this.checkCircular = checkCircular;
    this.allowNan = allowNan;
    this.sortKeys = sortKeys;
    this.indent = typeof indent === 'number' ? ' '.repeat(indent) : indent;

    if (separators !== null) {
      [this.itemSeparator, this.keySeparator] = separators;
    } else if (indent !== null) {
      // Matches CPython: an indent implies a bare comma so no trailing
      // whitespace is emitted before the newline.
      this.itemSeparator = ',';
      this.keySeparator = ': ';
    } else {
      this.itemSeparator = ', ';
      this.keySeparator = ': ';
    }

    this.defaultFn = defaultFn;
  }

  /** `JSONEncoder.default()` — reached only for unsupported types. */
  default(value) {
    if (this.defaultFn) return this.defaultFn(value);
    throw new PyTypeError(`Object of type ${typeof value} is not JSON serializable`);
  }

  /** The `floatstr()` closure built inside `JSONEncoder.iterencode()`. */
  floatstr(value) {
    let text;
    if (Number.isNaN(value)) text = 'NaN';
    else if (value === Infinity) text = 'Infinity';
    else if (value === -Infinity) text = '-Infinity';
    else return floatRepr(value);

    if (!this.allowNan) {
      throw new PyValueError(
