  *iterencode(value) {
    const markers = this.checkCircular ? new Set() : null;
    yield* this.#iterencode(value, 0, markers);
  }

  *#iterencodeList(lst, indentLevel, markers) {
    if (lst.length === 0) {
      yield '[]';
      return;
    }
    if (markers !== null) {
      if (markers.has(lst)) throw new PyValueError('Circular reference detected');
      markers.add(lst);
