    let entries = Array.from(dct.entries());
    if (this.sortKeys) entries = sortItems(entries);

    let first = true;
    for (const [rawKey, value] of entries) {
      let key = rawKey;
      if (isPyStr(key)) {
        // already a string
      } else if (isPyFloat(key)) key = this.floatstr(key);
      else if (key === true) key = 'true';
      else if (key === false) key = 'false';
      else if (isPyNone(key)) key = 'null';
      else if (isPyInt(key)) key = intRepr(key);
      else if (this.skipkeys) continue;
      else throw new PyTypeError('keys must be str, int, float, bool or None');

      if (first) first = false;
      else yield itemSeparator;

      yield encodeBasestring(key);
      yield this.keySeparator;

      if (isPyStr(value)) yield encodeBasestring(value);
      else if (isPyNone(value)) yield 'null';
      else if (value === true) yield 'true';
      else if (value === false) yield 'false';
      else if (isPyInt(value)) yield intRepr(value);
      else if (isPyFloat(value)) yield this.floatstr(value);
      else if (isPyList(value)) yield* this.#iterencodeList(value, level, markers);
      else if (isPyDict(value)) yield* this.#iterencodeDict(value, level, markers);
      else yield* this.#iterencode(value, level, markers);
    }

    if (newlineIndent !== null) {
      level -= 1;
      yield `\n${this.indent.repeat(level)}`;
    }
    yield '}';
    if (markers !== null) markers.delete(dct);
  }

  *#iterencode(value, indentLevel, markers) {
    if (isPyStr(value)) yield encodeBasestring(value);
    else if (isPyNone(value)) yield 'null';
    else if (value === true) yield 'true';
