  constructor(prog, { indentIncrement = 2, maxHelpPosition = 24, width = null } = {}) {
    let effectiveWidth = width;
    if (effectiveWidth === null) {
      effectiveWidth = Math.max(terminalColumns() - 2, 11);
    }
    this.prog = prog;
    this.indentIncrement = indentIncrement;
    this.maxHelpPosition = Math.min(maxHelpPosition, Math.max(effectiveWidth - 20, indentIncrement * 2));
