  /** `_get_option_tuples()` — abbreviation and attached-argument matching. */
  #getOptionTuples(argString) {
    const result = [];
    const chars = this.prefixChars;
    const isPrefix = (ch) => ch !== undefined && chars.includes(ch);

    if (isPrefix(argString[0]) && isPrefix(argString[1])) {
      if (!this.allowAbbrev) return result;
      let optionPrefix = argString;
      let explicitArg = null;
      const eq = argString.indexOf('=');
      if (eq !== -1) {
        optionPrefix = argString.slice(0, eq);
        explicitArg = argString.slice(eq + 1);
