  constructor({ prog, addHelp = true, allowAbbrev = true, prefixChars = '-' } = {}) {
    this.prog = prog;
    this.allowAbbrev = allowAbbrev;
    this.prefixChars = prefixChars;
    this.actions = [];
    this.optionStringActions = new Map();
    /** Mirrors argparse's two default groups; the first stays empty here. */
    this.groups = [
      { title: 'positional arguments', actions: [] },
      { title: 'options', actions: [] },
    ];
    this.hasNegativeNumberOptionals = [];

    if (addHelp) {
      this.addArgument(['-h', '--help'], {
        actionType: 'help',
        nargs: 0,
        help: 'show this help message and exit',
      });
    }
  }

  addArgument(optionStrings, { actionType = 'store', nargs = null, type = null, typeName = null, required = false, help = null, metavar = null } = {}) {
    const longest = optionStrings.find((s) => s.startsWith('--')) ?? optionStrings[0];
    const dest = longest.replace(/^-+/, '').replace(/-/g, '_');
    const action = { optionStrings, dest, actionType, nargs, type, typeName, required, help, metavar };
    this.actions.push(action);
    this.groups[1].actions.push(action);
    for (const optionString of optionStrings) {
      this.optionStringActions.set(optionString, action);
      if (NEGATIVE_NUMBER.test(optionString)) this.hasNegativeNumberOptionals.push(true);
    }
    return action;
  }

  #formatter() {
    return new HelpFormatter(this.prog);
  }

  formatUsage() {
    const text = this.#formatter().formatUsage(this.actions);
    return `${text.replace(/^\n+|\n+$/g, '')}\n`;
  }

  formatHelp() {
    const formatter = this.#formatter();
    return formatter.formatHelp(this.groups, this.actions);
  }

  exit(status = 0, message = null) {
    if (message) process.stderr.write(message);
    throw new SystemExit(status);
  }

  error(message) {
    process.stderr.write(this.formatUsage());
    this.exit(2, `${this.prog}: error: ${message}\n`);
  }

  /** `_get_option_tuples()` — abbreviation and attached-argument matching. */
  #getOptionTuples(argString) {
    const result = [];
    const chars = this.prefixChars;
    const isPrefix = (ch) => ch !== undefined && chars.includes(ch);

    if (isPrefix(argString[0]) && isPrefix(argString[1])) {
      if (!this.allowAbbrev) return result;
      let optionPrefix = argString;
      let explicitArg = null;
      const eq = argString.indexOf('=');
      if (eq !== -1) {
        optionPrefix = argString.slice(0, eq);
        explicitArg = argString.slice(eq + 1);
      }
      for (const [optionString, action] of this.optionStringActions) {
        if (optionString.startsWith(optionPrefix)) result.push({ action, optionString, explicitArg });
      }
    } else if (isPrefix(argString[0]) && !isPrefix(argString[1])) {
      const optionPrefix = argString;
      const shortOptionPrefix = argString.slice(0, 2);
      const shortExplicitArg = argString.slice(2);
      for (const [optionString, action] of this.optionStringActions) {
        if (optionString === shortOptionPrefix) {
          result.push({ action, optionString, explicitArg: shortExplicitArg });
        } else if (optionString.startsWith(optionPrefix)) {
          result.push({ action, optionString, explicitArg: null });
        }
      }
    }
    return result;
  }

  /** `_parse_optional()`; `null` means "treat as a positional". */
  #parseOptional(argString) {
    if (argString === '') return null;
    if (!this.prefixChars.includes(argString[0])) return null;

    if (this.optionStringActions.has(argString)) {
      return { action: this.optionStringActions.get(argString), optionString: argString, explicitArg: null };
    }
    if (argString.length === 1) return null;

    const eq = argString.indexOf('=');
    if (eq !== -1) {
      const optionString = argString.slice(0, eq);
      if (this.optionStringActions.has(optionString)) {
        return {
          action: this.optionStringActions.get(optionString),
          optionString,
          explicitArg: argString.slice(eq + 1),
        };
      }
    }

    const tuples = this.#getOptionTuples(argString);
    if (tuples.length > 1) {
      const matches = tuples.map((t) => t.optionString).join(', ');
      this.error(`ambiguous option: ${argString} could match ${matches}`);
    } else if (tuples.length === 1) {
      return tuples[0];
    }

    if (NEGATIVE_NUMBER.test(argString) && this.hasNegativeNumberOptionals.length === 0) return null;
    if (argString.includes(' ')) return null;

    return { action: null, optionString: argString, explicitArg: null };
  }

  /** `_get_value()` — run the action's `type` callable, reporting failures. */
  #getValue(action, argString) {
    if (!action.type) return argString;
    try {
      return action.type(argString);
    } catch {
      throw new ArgumentError(action, `invalid ${action.typeName} value: ${strRepr(argString)}`);
    }
  }

  /** `_get_values()`: drop the first `--`, then convert the single value. */
  #getValues(action, argStrings) {
    const values = argStrings.slice();
    const dashDash = values.indexOf('--');
    if (dashDash !== -1) values.splice(dashDash, 1);
    return this.#getValue(action, values[0]);
  }

  /** `_match_argument()` for `nargs=None` (`(-*A-*)`) and `nargs=0` (`(-*-*)`). */
  #matchArgument(action, pattern) {
    const regex = action.nargs === 0 ? /^(-*-*)/ : /^(-*A-*)/;
    const match = regex.exec(pattern);
    if (match === null || (action.nargs !== 0 && !match[1].includes('A'))) {
      throw new ArgumentError(action, 'expected one argument');
    }
    return match[1].length;
  }

  parseKnownArgs(argStrings) {
    const namespace = Object.create(null);
    const optionTuples = new Map();
    const pattern = [];
    let afterDoubleDash = false;

    for (let i = 0; i < argStrings.length; i += 1) {
      const argString = argStrings[i];
      if (!afterDoubleDash && argString === '--') {
        afterDoubleDash = true;
        pattern.push('-');
        continue;
      }
      if (afterDoubleDash) {
        pattern.push('A');
        continue;
      }
      const tuple = this.#parseOptional(argString);
      if (tuple === null) {
        pattern.push('A');
      } else {
        optionTuples.set(i, tuple);
        pattern.push('O');
      }
    }
    const patternText = pattern.join('');

    const seenActions = new Set();
    const extras = [];

    const takeAction = (action, args, optionString) => {
      seenActions.add(action);
      if (action.actionType === 'help') {
        process.stdout.write(this.formatHelp());
        this.exit(0);
        return;
      }
      namespace[action.dest] = this.#getValues(action, args);
    };

    const consumeOptional = (startIndex) => {
      const { action, explicitArg } = optionTuples.get(startIndex);
      if (action === null) {
        extras.push(argStrings[startIndex]);
        return startIndex + 1;
      }
      if (explicitArg !== null) {
        const argCount = this.#matchArgument(action, 'A');
        if (argCount === 1) {
          takeAction(action, [explicitArg], null);
          return startIndex + 1;
        }
        throw new ArgumentError(action, `ignored explicit argument ${strRepr(explicitArg)}`);
      }
      const start = startIndex + 1;
      const argCount = this.#matchArgument(action, patternText.slice(start));
      const stop = start + argCount;
      takeAction(action, argStrings.slice(start, stop), null);
      return stop;
    };

    const optionIndices = Array.from(optionTuples.keys()).sort((a, b) => a - b);
    const maxOptionIndex = optionIndices.length > 0 ? optionIndices[optionIndices.length - 1] : -1;

    let startIndex = 0;
    while (startIndex <= maxOptionIndex) {
      const nextOptionIndex = optionIndices.find((index) => index >= startIndex);
      if (startIndex !== nextOptionIndex) {
        // No positionals are defined, so everything before the next option is
        // simply unrecognised.
        extras.push(...argStrings.slice(startIndex, nextOptionIndex));
        startIndex = nextOptionIndex;
      }
      startIndex = consumeOptional(startIndex);
    }
    extras.push(...argStrings.slice(startIndex));

    const missing = this.actions
      .filter((action) => action.required && !seenActions.has(action))
      .map((action) => action.optionStrings.join('/'));
    if (missing.length > 0) {
      this.error(`the following arguments are required: ${missing.join(', ')}`);
    }

    return [namespace, extras];
  }

  parseArgs(argStrings) {
    let parsed;
