#!/usr/bin/env node
/**
 * Node.js port of `test10.py`.
 *
 * Reads three typed options, builds the same dict, and prints the canonical
 * encoding, the pretty encoding, and the number of chunks the iterative encoder
 * produces.  The first two lines are `bytes` reprs because `canonicaljson`
 * returns UTF-8 bytes and Python's `print()` reprs anything that is not a `str`.
 */

import {
  encodeCanonicalJson,
  encodePrettyPrintedJson,
  iterencodeCanonicalJson,
} from './lib/canonicaljson.mjs';
import { ArgumentParser, SystemExit } from './lib/argparse/parser.mjs';
import { PyException, printTraceback } from './lib/pyerrors.mjs';
import { pyFloatFromString } from './lib/pyfloat.mjs';
import { pyIntFromString } from './lib/pyint.mjs';
import { bytesRepr } from './lib/pyrepr.mjs';
import { pyDict } from './lib/pytypes.mjs';

function main() {
  const parser = new ArgumentParser({ prog: 'test10_executable' });
  parser.addArgument(['--a'], { type: (text) => text, typeName: 'str', required: true });
  parser.addArgument(['--b'], { type: pyIntFromString, typeName: 'int', required: true });
  parser.addArgument(['--c'], { type: pyFloatFromString, typeName: 'float', required: true });
  const args = parser.parseArgs(process.argv.slice(2));

  const data = pyDict([
    ['string', args.a],
    ['integer', args.b],
    ['float', args.c],
    ['list', [args.a, args.b, args.c]],
  ]);

  const canonicalResult = encodeCanonicalJson(data);
  const prettyResult = encodePrettyPrintedJson(data);
  const canonicalChunks = Array.from(iterencodeCanonicalJson(data));

  console.log(bytesRepr(canonicalResult));
  console.log(bytesRepr(prettyResult));
  console.log(String(canonicalChunks.length));
}

try {
  main();
} catch (err) {
  if (err instanceof SystemExit) {
    process.exitCode = err.code;
  } else if (err instanceof PyException) {
    printTraceback(err);
    process.exitCode = 1;
  } else {
    throw err;
  }
}

