/**
 * `argparse.HelpFormatter` — usage lines and the options section.
 *
 * The layout is width-sensitive in a way that is easy to get subtly wrong, so
 * the two derived quantities CPython computes up front are reproduced verbatim:
 * `_max_help_position` is clamped against the terminal width, and the usage
 * line is re-flowed part-by-part rather than by plain text wrapping.
 */

import { pyIntFromString } from '../pyint.mjs';

/** `shutil.get_terminal_size().columns`, honouring `$COLUMNS` first. */
export function terminalColumns() {
  const fromEnv = process.env.COLUMNS;
  if (fromEnv !== undefined) {
    try {
      const columns = Number(pyIntFromString(fromEnv));
      if (columns > 0) return columns;
    } catch {
      // Not an integer: fall through exactly as shutil's `except ValueError`.
    }
  }
  if (process.stdout.isTTY && process.stdout.columns > 0) return process.stdout.columns;
  return 80;
}

/** `textwrap.wrap()` over text whose whitespace has already been collapsed. */
function wrapText(text, width) {
  const limit = width < 1 ? 1 : width;
  const words = text.split(' ').filter((word) => word !== '');
  const pending = [];
  for (let i = words.length - 1; i >= 0; i -= 1) {
    pending.push(words[i]);
    if (i > 0) pending.push(' ');
  }

  const lines = [];
  while (pending.length > 0) {
    if (lines.length > 0 && pending[pending.length - 1] === ' ') pending.pop();

    const current = [];
    let length = 0;
    while (pending.length > 0 && length + pending[pending.length - 1].length <= limit) {
      const chunk = pending.pop();
      current.push(chunk);
      length += chunk.length;
    }
    if (pending.length > 0 && pending[pending.length - 1].length > limit) {
      const chunk = pending.pop();
      const room = limit - length;
      current.push(chunk.slice(0, room));
      pending.push(chunk.slice(room));
    }
    while (current.length > 0 && current[current.length - 1].trim() === '') current.pop();
    if (current.length > 0) lines.push(current.join(''));
  }
  return lines;
}

/** The default metavar for an optional: `dest.upper()`. */
function defaultMetavar(action) {
  return action.dest.toUpperCase();
}

/** `_format_action_invocation()` for an optional. */
function formatInvocation(action) {
  const joined = action.optionStrings.join(', ');
  if (action.nargs === 0) return joined;
  return `${joined} ${action.metavar ?? defaultMetavar(action)}`;
}

/** One usage fragment per action: `[-h]`, `--a A`, … */
function usageParts(actions) {
  return actions.map((action) => {
    let part;
    if (action.nargs === 0) part = action.optionStrings[0];
    else part = `${action.optionStrings[0]} ${action.metavar ?? defaultMetavar(action)}`;
    return action.required ? part : `[${part}]`;
  });
}

export class HelpFormatter {
  constructor(prog, { indentIncrement = 2, maxHelpPosition = 24, width = null } = {}) {
    let effectiveWidth = width;
    if (effectiveWidth === null) {
      effectiveWidth = Math.max(terminalColumns() - 2, 11);
    }
    this.prog = prog;
    this.indentIncrement = indentIncrement;
    this.maxHelpPosition = Math.min(maxHelpPosition, Math.max(effectiveWidth - 20, indentIncrement * 2));
    this.width = effectiveWidth;
  }

  /** `_format_usage()` including the part-wise re-flow for narrow terminals. */
  formatUsage(actions) {
    const prefix = 'usage: ';
    const prog = this.prog;
    const parts = usageParts(actions);
    let usage = [prog, ...parts].join(' ');

    const textWidth = this.width;
    if (prefix.length + usage.length > textWidth) {
      const getLines = (chunks, indent, linePrefix) => {
        const lines = [];
        let line = [];
        let lineLen = (linePrefix !== undefined ? linePrefix.length : indent.length) - 1;
        for (const part of chunks) {
          if (lineLen + 1 + part.length > textWidth && line.length > 0) {
            lines.push(indent + line.join(' '));
            line = [];
            lineLen = indent.length - 1;
          }
          line.push(part);
          lineLen += 1 + part.length;
        }
        if (line.length > 0) lines.push(indent + line.join(' '));
        if (linePrefix !== undefined && lines.length > 0) {
          lines[0] = lines[0].slice(indent.length);
        }
        return lines;
      };

      let lines;
      if (prefix.length + prog.length <= 0.75 * textWidth) {
        const indent = ' '.repeat(prefix.length + prog.length + 1);
        lines = parts.length > 0 ? getLines([prog, ...parts], indent, prefix) : [prog];
      } else {
        const indent = ' '.repeat(prefix.length);
        lines = [prog, ...getLines(parts, indent)];
      }
      usage = lines.join('\n');
    }

    return `${prefix}${usage}\n\n`;
  }

  /** The largest invocation width, used to align the help column. */
  actionMaxLength(actions) {
    let max = 0;
    for (const action of actions) {
      max = Math.max(max, formatInvocation(action).length + this.indentIncrement);
    }
    return max;
  }

  /** `_format_action()` for a single optional. */
  formatAction(action, actionMaxLength) {
    const indent = this.indentIncrement;
    const helpPosition = Math.min(actionMaxLength + 2, this.maxHelpPosition);
    const helpWidth = Math.max(this.width - helpPosition, 11);
    const actionWidth = helpPosition - indent - 2;
    const header = formatInvocation(action);

    const parts = [];
    let indentFirst = 0;
    if (!action.help) {
      parts.push(`${' '.repeat(indent)}${header}\n`);
    } else if (header.length <= actionWidth) {
      parts.push(`${' '.repeat(indent)}${header.padEnd(actionWidth)}  `);
      indentFirst = 0;
    } else {
      parts.push(`${' '.repeat(indent)}${header}\n`);
      indentFirst = helpPosition;
    }

    if (action.help && action.help.trim()) {
      const collapsed = action.help.replace(/\s+/g, ' ').trim();
      const helpLines = wrapText(collapsed, helpWidth);
      parts.push(`${' '.repeat(indentFirst)}${helpLines[0]}\n`);
      for (const line of helpLines.slice(1)) {
        parts.push(`${' '.repeat(helpPosition)}${line}\n`);
      }
    } else if (!parts[parts.length - 1].endsWith('\n')) {
      parts.push('\n');
    }

    return parts.join('');
  }

  /**
   * `ArgumentParser.format_help()`: usage, then one section per action group.
   * Empty groups vanish; runs of blank lines collapse to one; the whole thing
   * is stripped of surrounding newlines and given a single trailing one.
   */
  formatHelp(groups, actions) {
    const actionMaxLength = this.actionMaxLength(actions);
    let text = this.formatUsage(actions);

    for (const group of groups) {
      const body = group.actions.map((action) => this.formatAction(action, actionMaxLength)).join('');
      if (!body) continue;
      text += `\n${group.title}:\n${body}\n`;
    }

    return `${text.replace(/\n\n\n+/g, '\n\n').replace(/^\n+|\n+$/g, '')}\n`;
  }
}
